// Blocco 31 – Manuali INAIL: «Prevenzione incendi per attività di autorimesse» (2023) e «per attività commerciali» (2024).
const IAU = "Manuale INAIL – Prevenzione incendi per attività di autorimesse (RTV V.6, 2023)";
const ICO = "Manuale INAIL – Prevenzione incendi per attività commerciali (RTV V.8, 2024)";

// --- Approccio prescrittivo e prestazionale
D("in10","codg",[IAU],"Secondo il manuale INAIL, il principale vantaggio dell'approccio prescrittivo è:",["L'agevole e omogenea applicazione e la ragionevole aspettativa di uniformità di giudizio dei controllori.","L'estrema flessibilità delle soluzioni.","La possibilità di simulare incendi complessi."]);
D("in11","codg",[IAU],"Secondo il manuale INAIL, il maggiore svantaggio dell'approccio prescrittivo è:",["L'estrema rigidità, che spesso obbliga a ricorrere alla deroga.","L'elevato onere computazionale.","La difficoltà di validare i modelli."]);
D("in12","codg",[IAU],"Secondo il manuale INAIL, tra i limiti dell'approccio prestazionale (FSE) ci sono:",["La validazione dei modelli di calcolo e la forte preparazione richiesta a progettisti e controllori.","L'impossibilità di simulare incendi complessi.","L'obbligo di ricorrere sempre alla deroga."]);
D("in13","fse",[IAU],"I modelli di campo, secondo il manuale INAIL, stimano l'evoluzione dell'incendio risolvendo numericamente:",["Le equazioni di Navier-Stokes.","Le equazioni di Bernoulli per i soli fluidi incomprimibili.","Le sole equazioni di bilancio energetico a due zone."]);
D("in14","fse",[IAU],"Prima del Codice, secondo il manuale INAIL, la Fire Safety Engineering in Italia era usata essenzialmente per:",["Attività non normate e istanze di deroga per dimostrare la sicurezza equivalente.","Tutte le attività soggette.","Solo per le attività di categoria A."]);

// --- DM 1/2/1986 e autorimesse
D("in20","rtv",[IAU],"Secondo il DM 1 febbraio 1986, un'autorimessa è di tipo «isolato» quando:",["È situata in edificio esclusivamente destinato a tale uso, eventualmente adiacente ad altri, strutturalmente e funzionalmente separato.","Dista almeno 100 m da altri edifici.","Ha meno di nove autoveicoli."]);
D("in21","rtv",[IAU],"Secondo il DM 1/2/1986, un'autorimessa è «aperta» se le aperture perimetrali su spazio a cielo libero realizzano un'aerazione permanente:",["Non inferiore al 60% della superficie delle pareti e comunque superiore al 15% della superficie in pianta.","Non inferiore al 25% della superficie in pianta.","Non inferiore a 1/30 della superficie in pianta."]);
D("in22","rtv",[IAU],"Secondo il DM 1/2/1986, un'autorimessa con piano di parcamento sotto quota è considerata «fuori terra» se l'intradosso del solaio supera il piano di riferimento di almeno:",["0,6 m, con aperture di aerazione alte almeno 0,5 m.","2 m, con aperture alte almeno 1 m.","0,3 m, senza altri requisiti."]);
D("in23","rtv",[IAU],"Secondo il DM 1/2/1986, un'autorimessa «sorvegliata» è quella:",["Provvista di sistemi automatici di controllo antincendio o di vigilanza continua almeno durante l'orario di apertura.","Con custode residente nell'edificio.","Con meno di 50 posti auto."]);
D("in24","rtv",[IAU],"Secondo il manuale INAIL, la superficie complessiva dell'autorimessa (soglia dei 300 m²) è:",["La superficie lorda al netto delle pertinenze compartimentate: somma di aree TA, TB e TM1 non compartimentate.","La superficie dell'intero edificio.","La sola superficie dei posti auto."]);
D("in25","rtv",[IAU],"Nella RTV V.6 le aree di minuta manutenzione dei veicoli (TB) devono avere superficie non superiore:",["Al 30% del compartimento ed essere collocate a quota superiore a −6 m.","Al 50% del compartimento, a qualsiasi quota.","A 25 m²."]);
D("in27","rtv",[IAU],"Secondo il manuale INAIL, si può ancora applicare il DM 1/2/1986 a un ampliamento di autorimessa esistente quando:",["L'applicazione del Codice alla nuova porzione determinerebbe incompatibilità con le porzioni esistenti non interessate.","Lo decide il titolare senza motivazione.","L'autorimessa è sotto i 300 m²."]);
D("in28","proc",[IAU],"Secondo la circolare 3277/2016 richiamata dal manuale INAIL, la deroga è proponibile solo se:",["Esiste una regola tecnica ufficiale da derogare e si individuano misure che garantiscono sicurezza equivalente.","Esiste una linea guida o una guida tecnica.","L'attività è di categoria A."]);
D("in29","proc",[IAU],"Secondo il manuale INAIL, non è possibile chiedere la deroga a:",["Linee guida, linee di indirizzo e guide tecniche.","Regole tecniche verticali.","Regole tecniche tradizionali."]);
D("in30","rtv",[IAU],"Nel caso studio INAIL, la deroga al DM 1/2/1986 riguardava tra l'altro scale/ascensori REI 90 invece di REI 120 e larghezza delle uscite di 0,90 m invece di:",["1,20 m (due moduli).","1,80 m.","0,80 m."]);
D("in31","rtv",[IAU],"Secondo il manuale INAIL, rispetto al GPL, le auto alimentate a metano:",["Non sono soggette a limitazioni, perché il metano tende a salire e non si accumula in basso.","Sono vietate nei piani interrati.","Hanno lo stesso rischio di accumulo a pavimento."]);
D("in32","rtv",[IAU],"Secondo il manuale INAIL, per le auto elettriche una criticità specifica è che:",["La combustione delle batterie agli ioni di litio può manifestarsi anche in modo differito, anche dopo giorni.","Non possono mai incendiarsi.","Producono solo incendi di classe A."]);

// --- Attività commerciali: DM 27/7/2010 e caso studio
D("in40","rtv",[ICO],"Secondo il DM 27/7/2010 richiamato dal manuale INAIL, la densità di affollamento nelle aree di vendita del settore non alimentare è:",["0,2 persone/m².","0,4 persone/m².","0,7 persone/m²."]);
D("in41","rtv",[ICO],"Secondo il DM 27/7/2010, nelle aree di vendita del settore alimentare o misto fino a 2500 m² la densità di affollamento è:",["0,4 persone/m².","0,2 persone/m².","1,2 persone/m²."]);
D("in42","rtv",[ICO],"Secondo il DM 27/7/2010, per le aree di ristorazione delle attività commerciali la densità di affollamento è:",["0,7 persone/m².","0,4 persone/m².","2 persone/m²."]);
D("in43","rtv",[ICO],"Nei centri commerciali (DM 27/7/2010), per le parti comuni frequentate dal pubblico la densità di affollamento è non inferiore a:",["0,2 persone/m².","0,1 persone/m².","0,7 persone/m²."]);
D("in44","rtv",[ICO],"Secondo il DM 27/7/2010, se l'affollamento delle aree di ristorazione supera 200 persone:",["Almeno la metà delle uscite di emergenza deve immettere direttamente all'esterno o su luogo sicuro dinamico.","Serve un impianto sprinkler dedicato.","Va presentata istanza di deroga."]);
D("in45","rtv",[ICO],"Secondo il DM 27/7/2010, per aree temporanee per mostre o intrattenimento con capienza oltre 100 persone si considera una densità di:",["1,2 persone/m², in aggiunta all'affollamento delle superfici di vendita.","0,4 persone/m².","0,2 persone/m²."]);
D("in46","rtv",[ICO],"Secondo il DM 27/7/2010, la capacità di deflusso per locali con pavimento a quota compresa tra ±1 m dal piano di riferimento non deve superare:",["50.","37,5.","33."]);
D("in47","rtv",[ICO],"La RTV V.8 si applica alle attività commerciali con superficie lorda, comprensiva di servizi, depositi e spazi comuni coperti, superiore a:",["400 m².","200 m².","1000 m²."]);
D("in48","rtv",[ICO],"Nel caso studio INAIL, un centro commerciale con A > 10000 m² e piani tra −5 m e 12 m è classificato:",["AE e HB.","AC e HA.","AD e HC."]);
D("in49","fse",[ICO],"Nel caso studio INAIL del centro commerciale, la soluzione alternativa con FSE ha mostrato che:",["Non era possibile posizionare un'autovettura nel portico al piano terra senza compromettere la salvaguardia della vita.","Lo sprinkler nella mall era superfluo in ogni caso.","Le vie d'esodo erano sovradimensionate del 50%."]);
D("in50","fse",[ICO],"Nel caso studio INAIL, la GSA risulta fondamentale anche per garantire:",["La disponibilità superiore degli impianti di controllo dell'incendio ipotizzata in progetto.","L'esonero dal rinnovo periodico.","La riduzione del carico d'incendio a zero."]);
